insert into public.referencias (chave, citacao, doi_url, nivel, resumo, sustenta) values
('halperin2022', 'Halperin I, Malleron T, Har-Nir I, et al. Accuracy in Predicting Repetitions to Task Failure in Resistance Exercise: A Scoping Review and Exploratory Meta-analysis. Sports Med. 2022;52:377-390.', 'https://doi.org/10.1007/s40279-021-01559-x', 'moderada', 'Quem treina erra, em média, por volta de 1 repetição ao estimar quantas faltam para a falha, e erra mais em séries longas.', array['Tolerância de 1 no RIR anotado (regras 5 e 6)', 'Não reduzir a carga por um único treino ruim (regras 3 e 7)', 'Abaixo da faixa num dia de prontidão baixa vira manter (P3)']::text[]),
('hickmott2022', 'Hickmott LM, Chilibeck PD, Shaw KA, et al. The Effect of Load and Volume Autoregulation on Muscular Strength and Hypertrophy: A Systematic Review and Meta-Analysis. Sports Med Open. 2022;8:9.', 'https://doi.org/10.1186/s40798-021-00404-9', 'moderada', 'Ajustar a carga pelo esforço percebido (RIR/RPE) rendeu ganhos de força e hipertrofia semelhantes aos da prescrição fixa.', array['Motor de carga autorregulado por reps e RIR (regras 4 a 7)']::text[]),
('bosquet2013', 'Bosquet L, Berryman N, Dupuy O, et al. Effect of training cessation on muscular performance: a meta-analysis. Scand J Med Sci Sports. 2013;23(3).', 'https://doi.org/10.1111/sms.12047', 'forte', 'Parar de treinar reduz força e potência, e a perda cresce com a duração da pausa (relação dose-resposta, 103 estudos).', array['Reduzir a carga na volta de uma pausa longa (regra 1)']::text[]),
('craven2022', 'Craven J, McCartney D, Desbrow B, et al. Effects of Acute Sleep Loss on Physical Performance: A Systematic and Meta-Analytical Review. Sports Med. 2022;52:2669-2690.', 'https://doi.org/10.1007/s40279-022-01706-y', 'forte', 'Dormir 6 h ou menos piora o desempenho físico no dia seguinte, com efeitos em força e resistência de força (69 publicações).', array['Prontidão baixa com sono abaixo de 6 h (check-in)', 'Nada de aumento num dia de prontidão baixa (P1)', 'Queda num dia de sono ruim não conta como queda consistente (P2)']::text[]),
('murphy2022', 'Murphy C, Koehler K. Energy deficiency impairs resistance training gains in lean mass but not strength: A meta-analysis and meta-regression. Scand J Med Sci Sports. 2022;32(1):125-137.', 'https://doi.org/10.1111/sms.14075', 'moderada', 'Treinar em déficit calórico atrapalha o ganho de massa magra, mas não o de força; um déficit de ~500 kcal/dia já impediu o ganho de massa magra.', array['O déficit não muda a expectativa de força do motor', 'Alerta do coach de risco à massa magra com perda de peso rápida (P5)']::text[]),
('galaxybia2025', 'Carrier B, Melvin AC, Outwin JR, et al. Wearables for health monitoring: body composition estimates of commercial smartwatch and clinical bioelectrical impedance device. Front Sports Act Living. 2025;7:1644082.', 'https://doi.org/10.3389/fspor.2025.1644082', 'limitada', 'Em 108 pessoas ativas, o Galaxy Watch5 acompanhou bem o percentual de gordura do DXA no grupo, mas com erro individual grande, e foi fraco para músculo esquelético.', array['Bioimpedância do relógio mostrada como tendência, com aviso de precisão', 'Músculo esquelético com destaque menor']::text[]),
('taco2011', 'NEPA/UNICAMP. Tabela Brasileira de Composição de Alimentos – TACO. 4ª ed. Campinas: NEPA-UNICAMP; 2011.', null, 'forte', 'Tabela oficial de composição de alimentos brasileiros (597 alimentos), com reprodução permitida citando a fonte.', array['Base de alimentos, totais do plano alimentar e substituições']::text[]),
('convencao-pausa', 'Convenção prática do Repz (sem estudo direto).', null, 'pratica', 'A redução só começa a partir de 3 semanas sem o exercício e é de 10%: números escolhidos para ficar do lado seguro, não tirados de um estudo.', array['Regra 1: pausa de 21 dias e −10%']::text[]),
('convencao-descanso', 'Convenção prática do Repz (sem estudo direto).', null, 'pratica', 'Menos de 48 h entre duas sessões do mesmo exercício gera só um aviso; não muda a carga.', array['P4: pouco descanso desde a última vez']::text[]),
('convencao-perda-peso', 'Convenção prática do Repz (sem estudo direto).', null, 'pratica', 'Perder mais de 0,7% do peso por semana, duas semanas seguidas, é tratado como ritmo rápido o bastante para o coach alertar.', array['P5: alerta de risco à massa magra']::text[])
